using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Preserve EF Core 8 discriminator property name (EF9 defaults to "$type").
            // Existing 500K documents use "Discriminator" and direct SQL queries reference it.
            entity.HasDiscriminator<string>("Discriminator");

            // Preserve EF Core 8 compound id format "Product|123" (EF9 defaults to key-only).
            // Existing documents use the old format; FindAsync would fail without this.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // HasIndex removed — Cosmos DB does not support EF-managed indexes (EF9 now throws).
        // Manage indexing policy via Azure Portal, Bicep, or Terraform.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

